<template>
  <section id="our-projects" class="our-projects">
    <div class="our-project-texts">
      <!-- <p class="what-we-do">What We Do</p> -->
      <h2>Our Projects</h2>
      <p class="what-we-do-p2">
        We've completed numerous dynamic projects, consistently delivering
        outstanding results that surpass our clients' expectations.
      </p>
    </div>
    <div class="gallery">
      <div
        class="gallery-container"
        :style="{ transform: `translateX(${translateX}%)` }"
      >
        <img
          v-for="(image, index) in images"
          :key="index"
          :src="image"
          alt="Gallery Image"
          class="gallery-image"
        />
      </div>

      <button class="gallery-button gallery-button-prev" @click="prevSlide">
        <span class="arrow">‹</span>
      </button>

      <button class="gallery-button gallery-button-next" @click="nextSlide">
        <span class="arrow">›</span>
      </button>

      <div class="gallery-indicators">
        <span
          v-for="(image, index) in images"
          :key="index"
          class="indicator"
          :class="{ active: currentIndex === index }"
          @click="goToSlide(index)"
          @keydown.enter="goToSlide(index)"
          tabindex="0"
        >
        </span>
      </div>
    </div>
  </section>
</template>

<!-- ////////////////////////////////// -->
<script>
import image1 from "@/assets/g-img-1.jpg";
import image2 from "@/assets/g-img-2.jpg";
import image3 from "@/assets/g-img-3.jpg";
import image4 from "@/assets/g-img-4.jpg";
import image5 from "@/assets/g-img-5.jpg";
import image6 from "@/assets/g-img-6.jpg";

export default {
  data() {
    return {
      images: [image1, image2, image3, image4, image5, image6],
      currentIndex: 0,
      intervalId: null, // Add intervalId to store the interval
    };
  },
  computed: {
    translateX() {
      return -this.currentIndex * 100;
    },
  },
  mounted() {
    this.startAutoplay();
  },
  beforeUnmount() {
    this.stopAutoplay();
  },
  methods: {
    nextSlide() {
      this.currentIndex = (this.currentIndex + 1) % this.images.length;
    },
    prevSlide() {
      this.currentIndex =
        (this.currentIndex - 1 + this.images.length) % this.images.length;
    },
    goToSlide(index) {
      this.currentIndex = index;
    },
    startAutoplay() {
      this.intervalId = setInterval(() => {
        // change from this.nextSlide to an anonymous function
        this.nextSlide();
      }, 9000); // Set interval to 6000ms (6 seconds)
    },
    stopAutoplay() {
      clearInterval(this.intervalId);
    },
  },
};
</script>

