<template>
  <div class="category-gallery">
    <div class="gallery-items">
      <div
        v-for="(image, index) in images"
        :key="index"
        class="gallery-item"
        @click="openFullscreen(index)"
      >
        <img :src="image.src" :alt="image.alt" />
      </div>
    </div>

    <div v-if="fullscreenImage" class="fullscreen-overlay" @click="closeFullscreen">
      <button class="close-button">X</button>

      <button class="nav-button nav-button-prev" @click.stop="prevImage">
        <
      </button>
      <button class="nav-button nav-button-next" @click.stop="nextImage">
        >
      </button>

      <div class="fullscreen-content">
        <img :src="fullscreenImage.src" :alt="fullscreenImage.alt" />
        <p class="fullscreen-description">{{ fullscreenImage.description }}</p>

        <div class="thumbnail-navigation">
          <button
            v-for="(img, idx) in images"
            :key="idx"
            class="thumbnail"
            @click.stop="goToImage(idx)"
            :class="{ 'active': idx === currentFullscreenIndex }"
          >
            <img :src="img.src" :alt="img.alt" />
          </button>
        </div>
      </div>
    </div>
  </div>
</template>

<script>
export default {
    props: {
        images: {
            type: Array,
            required: true
        }
    },
  data() {
    return {
      currentHoveredIndex: null,
      fullscreenImage: null,
      currentFullscreenIndex: 0,
    };
  },
  methods: {
    openFullscreen(index) {
      this.fullscreenImage = this.images[index];
      this.currentFullscreenIndex = index;
      document.body.style.overflow = 'hidden'; // Prevent background scrolling
    },
    closeFullscreen() {
      this.fullscreenImage = null;
      document.body.style.overflow = ''; // Allow background scrolling
    },
    goToImage(index) {
      this.currentFullscreenIndex = index;
      this.fullscreenImage = this.images[index];
    },
    prevImage() {
      this.currentFullscreenIndex =
        (this.currentFullscreenIndex - 1 + this.images.length) % this.images.length;
      this.fullscreenImage = this.images[this.currentFullscreenIndex];
    },
    nextImage() {
      this.currentFullscreenIndex = (this.currentFullscreenIndex + 1) % this.images.length;
      this.fullscreenImage = this.images[this.currentFullscreenIndex];
    },
  },
};
</script>

<style scoped>
/* General Styling */
.category-gallery {
  width: 100%;
}

/* Gallery Items (Grid Layout) */
.gallery-items {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(400px, 1fr));
  gap: 20px;
  padding: 20px;
}

.gallery-item {
  position: relative;
  cursor: pointer;
  overflow: hidden;
}

.gallery-item img {
  width: 100%;
  height: 400px;
  object-fit: cover;
  transition: transform 0.3s ease;
}

.gallery-item:hover img {
  transform: scale(1.05);
}

/* Fullscreen Overlay */
.fullscreen-overlay {
  position: fixed;
  top: 0;
  left: 0;
  width: 100%;
  height: 100%;
  background-color: rgba(0, 0, 0, 0.9);
  display: flex;
  justify-content: center;
  align-items: center;
  z-index: 1000;
  overflow: auto; /* Enable scrolling if content overflows */
}

.fullscreen-content {
  max-width: 80%; /* Adjust as needed */
  max-height: 90%; /* Adjust as needed */
  text-align: center;
  position: relative; /* Required for positioning buttons */
}

.fullscreen-content img {
  max-width: 100%;
  max-height: 70vh; /* Adjust as needed */
  object-fit: contain;
}

.fullscreen-description {
  color: white;
  margin-top: 20px;
}

/* Thumbnail Navigation */
.thumbnail-navigation {
  display: flex;
  justify-content: center;
  margin-top: 20px;
  overflow-x: auto; /* Enable horizontal scrolling */
  padding-bottom: 10px; /* Add some padding for the scrollbar */
}

.thumbnail {
  width: 100px;
  height: 100px;
  border: 2px solid transparent;
  margin: 0 10px;
  cursor: pointer;
}

.thumbnail img {
  width: 100%;
  height: 100%;
  object-fit: cover;
}

.thumbnail.active {
  border-color: #d8d300; /* Highlight active thumbnail */
}

/* Navigation Buttons (Next/Prev in Fullscreen) */
.nav-button {
  position: absolute;
  top: 40%;
  transform: translateY(-50%);
  background-color: rgba(0, 0, 0, 0.5);
  color: white;
  border: 1px solid white;
  border-radius: 50%;
  width: 60px;
  height: 60px;
  display: flex;
  justify-content: center;
  align-items: center;
  cursor: pointer;
  font-size: 20px;
  transition: background-color 0.3s ease;
  z-index: 1001;  /* Ensure buttons are above other elements */
}

.nav-button:hover {
  background-color: rgba(172, 172, 172, 0.8);
}

.nav-button-prev {
  left: 20px;
}

.nav-button-next {
  right: 20px;
}

.close-button {
  position: absolute;
  top: 20px;
  right: 20px;
  color: #d8d300;
  font-size: 2rem;
  cursor: pointer;
  background-color: transparent;
  border: none;
}
</style>